#!/usr/bin/env python3
import ast,base64,os,subprocess,time,urllib.request
from pathlib import Path
ROOT=Path('/opt/bot-office')
AGENT=base64.b64decode('')
JS=base64.b64decode('').decode()
def main():
 if os.geteuid()!=0:raise SystemExit('sudo python3 bot_office_risk_update.py 로 실행하세요.')
 server=ROOT/'server.py';index=ROOT/'index.html';unit=Path('/etc/systemd/system/bot-office-inventory.service')
 src=server.read_text();html=index.read_text();service=unit.read_text()
 if 'BOT_OFFICE_RISK_V1' in src:raise SystemExit('이미 적용되어 있습니다. 변경 없음.')
 if 'BOT_OFFICE_INVENTORY_V1' not in src:raise SystemExit('먼저 inventory 업데이트가 필요합니다. 변경 없이 중단.')
 if src.count("    data = {'observed_at':")!=1 or html.count('const reports=[')!=1 or html.count('const gib=x=>')!=1:raise SystemExit('예상과 다른 버전입니다. 변경 없이 중단.')
 anchor="    data = {'observed_at':"
 add="""    # BOT_OFFICE_RISK_V1
    try:
        risk_report = json.loads(Path('/var/lib/bot-office/risk_report.json').read_text())
    except (OSError, ValueError):
        risk_report = None
"""
 updated=src.replace(anchor,add+anchor).replace("'inventory':inventory,", "'risk_report':risk_report, 'inventory':inventory,")
 ast.parse(updated);ast.parse(AGENT)
 start=html.index('const reports=[');end=html.index(';\nconst $=',start)
 patched=html[:start]+'let reports=[]'+html[end:]
 patched=patched.replace('const gib=x=>',JS+'const gib=x=>')
 patched=patched.replace('<strong>03 <small>건</small></strong>','<strong id="reportCount">— <small>건</small></strong>')
 patched=patched.replace('예시 보고 · 사실 확인과 구분','실제 운영 규칙 점검 · 1분 주기').replace('예시 3건','실제 운영 점검').replace('예시 보고서','실제 운영 점검 · 가상매매 제외')
 patched=patched.replace("state:'모의 점검 예시'","state:'실제 규칙 점검'")
 patched=patched.replace('부서 활동·보고·승인 기능은 시연이며','대비팀 운영 보고만 실제이며, 나머지 부서 활동·승인은 시연입니다. 또한')
 run='ExecStart=/usr/bin/python3 /opt/bot-office/risk_agent.py'
 if 'Type=oneshot' not in service or run in service:raise SystemExit('예상과 다른 수집 서비스. 변경 없이 중단.')
 updated_service=service.replace('Type=oneshot','Type=oneshot\n'+run)
 # Keep inventory collection first; insert risk step after the existing collector command.
 updated_service=service.replace('ExecStart=/usr/bin/python3 /opt/bot-office/collect_inventory.py','ExecStart=/usr/bin/python3 /opt/bot-office/collect_inventory.py\n'+run)
 if updated_service==service:raise SystemExit('수집 실행 경로 확인 실패. 변경 없이 중단.')
 backup=ROOT/('backup_risk_'+time.strftime('%Y%m%d_%H%M%S'));backup.mkdir()
 for file,text in ((server,src),(index,html),(backup/'inventory.service',service)):
  if file.parent==backup:file.write_text(text)
  else:(backup/file.name).write_text(text)
 agent=ROOT/'risk_agent.py';agent.write_bytes(AGENT);agent.chmod(0o644)
 subprocess.run(['/usr/bin/python3',str(agent)],check=True,timeout=20)
 try:
  for file,text in ((server,updated),(index,patched),(unit,updated_service)):
   temp=file.with_suffix('.new');temp.write_text(text);temp.chmod(0o644);os.replace(temp,file)
  subprocess.run(['systemctl','daemon-reload'],check=True)
  subprocess.run(['systemctl','start','bot-office-inventory.service'],check=True,timeout=40)
  subprocess.run(['systemctl','restart','bot-office.service'],check=True)
  for _ in range(10):
   try:
    with urllib.request.urlopen('http://127.0.0.1:8765/healthz',timeout=2) as r:
     if r.status==200:break
   except OSError:time.sleep(.5)
  else:raise RuntimeError('health check failed')
 except Exception:
  server.write_text(src);index.write_text(html);unit.write_text(service)
  subprocess.run(['systemctl','daemon-reload']);subprocess.run(['systemctl','restart','bot-office.service'])
  raise SystemExit('업데이트 실패: 기존 버전으로 복구했습니다. 오류를 보내주세요.')
 import json
 data=json.loads(Path('/var/lib/bot-office/risk_report.json').read_text())
 print('완료: 대비팀 규칙 점검 연결 / 현재 보고 '+str(len(data['reports']))+'건')
 for r in data['reports']:print(r['level']+' | '+r['title'])
 print('기존 봇 변경 없음. 사무실에 다시 로그인하세요. 백업: '+str(backup))
if __name__=='__main__':main()
